enum LangId { LANG_RU = 0, LANG_EN = 1, LANG_FR = 2, LANG_DE = 3, LANG_ZH = 4, LANG_JA = 5 };
inline std::atomic<int> g_lang{ LANG_RU };

inline const wchar_t* LangCode(int l) {
    static const wchar_t* c[] = { L"ru", L"en", L"fr", L"de", L"zh", L"ja" };
    return (l >= 0 && l <= 5) ? c[l] : L"ru";
}
inline int LangFromCode(const std::wstring& s) {
    if (s == L"en") return LANG_EN;
    if (s == L"fr") return LANG_FR;
    if (s == L"de") return LANG_DE;
    if (s == L"zh") return LANG_ZH;
    if (s == L"ja") return LANG_JA;
    return LANG_RU;
}
inline const wchar_t* LangLocale(int l) {
    static const wchar_t* c[] = { L"ru-RU", L"en-US", L"fr-FR", L"de-DE", L"zh-CN", L"ja-JP" };
    return (l >= 0 && l <= 5) ? c[l] : L"ru-RU";
}
inline const wchar_t* LangName(int l) {
    static const wchar_t* c[] = { L"Русский", L"English", L"Français", L"Deutsch", L"中文", L"日本語" };
    return (l >= 0 && l <= 5) ? c[l] : L"Русский";
}

