static const size_t kTrRowCount = sizeof(kTrRows) / sizeof(kTrRows[0]);

inline const std::unordered_map<std::wstring, const TrRow*>& TrMap() {
    static const auto m = [] {
        std::unordered_map<std::wstring, const TrRow*> r;
        r.reserve(kTrRowCount * 2);
        for (auto& e : kTrRows) r.emplace(e.ru, &e);
        return r;
    }();
    return m;
}

inline bool TrHasCyrillic(const std::wstring& s) {
    for (wchar_t c : s) if (c >= 0x0400 && c <= 0x04FF) return true;
    return false;
}

inline const wchar_t* TrExact(const std::wstring& s, int l) {
    if (l == LANG_RU) return nullptr;
    auto it = TrMap().find(s);
    if (it == TrMap().end()) return nullptr;
    const wchar_t* p = it->second->t[l - 1];
    return p ? p : it->second->t[LANG_EN - 1];
}

struct TrFragList {
    std::vector<const TrRow*> rows;
    TrFragList() {
        for (auto& e : kTrRows) {
            std::wstring w(e.ru);
            if (w.size() < 3) continue;
            bool frag = false;
            if (w == L"Популярное") frag = true;
            for (wchar_t c : w) {
                if (c == L' ' || c == L'\u00ab' || c == L'\u00bb' || c == L':' ||
                    c == L'(' || c == L')' || c == L'!' || c == L'\u2026' ||
                    c == L'\u2014' || c == L'\u00b7' || c == L'?' || c == L',' || c == L'.') {
                    frag = true; break;
                }
            }
            if (frag) rows.push_back(&e);
        }
        std::sort(rows.begin(), rows.end(), [](const TrRow* a, const TrRow* b) {
            return std::wcslen(a->ru) > std::wcslen(b->ru);
        });
    }
};

inline const TrFragList& TrFrags() { static const TrFragList f; return f; }

inline std::wstring TrText(const std::wstring& s) {
    int l = g_lang.load(std::memory_order_relaxed);
    if (l == LANG_RU || !TrHasCyrillic(s)) return s;
    if (const wchar_t* e = TrExact(s, l)) return e;
    std::wstring out = s;
    for (const TrRow* r : TrFrags().rows) {
        const wchar_t* tr = r->t[l - 1];
        if (!tr || !*tr) continue;
        std::wstring needle(r->ru);
        size_t pos = 0;
        while ((pos = out.find(needle, pos)) != std::wstring::npos) {
            out.replace(pos, needle.size(), tr);
            pos += std::wcslen(tr);
        }
    }
    return out;
}
